function validate(input) {
  const [fnName, objects, inputs] = input;
  if (!['sum', 'merge', 'list'].includes(fnName)) return 'fn must be "sum", "merge" or "list".';
  if (!Array.isArray(objects) || objects.length > 1000) return 'objects must be a list of at most 1000 entries.';
  if (!objects.every(o => o !== null && typeof o === 'object')) return 'Each entry of objects must be a JSON object or array.';
  if (!Array.isArray(inputs) || inputs.length < 1 || inputs.length > 100000) return 'Give 1 to 10^5 argument lists.';
  let total = 0;
  for (const args of inputs) {
    if (!Array.isArray(args)) return 'Each entry of inputs must be a list of arguments.';
    total += args.length;
    if (total > 100000) return 'inputs may hold at most 10^5 arguments in total.';
    for (const arg of args) {
      const isRef = arg !== null && typeof arg === 'object';
      if (isRef) {
        const keys = Object.keys(arg);
        if (Array.isArray(arg) || keys.length !== 1 || keys[0] !== 'ref' || !Number.isInteger(arg.ref) || arg.ref < 0 || arg.ref >= objects.length) {
          return 'Write an object argument as { "ref": i } with i an index into objects.';
        }
      } else if (typeof arg === 'number') {
        if (!Number.isInteger(arg) || Math.abs(arg) > 1e9) return 'Numbers must be integers from -10^9 to 10^9.';
      } else if (arg !== null && typeof arg !== 'string' && typeof arg !== 'boolean') {
        return 'Each argument is a number, string, boolean, null or { "ref": i }.';
      }
      if (fnName === 'sum' && typeof arg !== 'number') return 'Every argument of sum must be a number.';
      if (fnName === 'merge' && (!isRef || Array.isArray(objects[arg.ref]))) return 'Every argument of merge must refer to an object that is not an array.';
    }
  }
  return null;
}

