function adapt(input, solve, kit) {
  const [fnName, objects, inputs] = input;
  // Each entry of objects becomes one real object, shared by every { ref } that names it.
  const pool = objects.map(o => JSON.parse(JSON.stringify(o)));
  const plain = {
    sum: (...args) => args.reduce((total, value) => total + value, 0),
    merge: (...args) => Object.assign({}, ...args),
    list: (...args) => [...args],
  }[fnName];
  let calls = 0;
  const fn = function (...args) {
    calls += 1;
    kit.trace(`${fnName} runs (run ${calls})`);
    return plain(...args);
  };
  const memoized = solve(fn);
  if (typeof memoized !== 'function') throw new Error('memoize must return a function.');
  const answer = [];
  for (const list of inputs) {
    const args = list.map(arg => (arg !== null && typeof arg === 'object' ? pool[arg.ref] : arg));
    const shown = list.map(arg => (arg !== null && typeof arg === 'object' ? `objects[${arg.ref}]` : JSON.stringify(arg))).join(', ');
    kit.trace(`memoized(${shown}) is called`);
    const val = memoized(...args);
    kit.trace(`It returns ${JSON.stringify(val)}; fn has run ${calls} times`);
    answer.push({ val, calls });
  }
  return answer;
}

