function memoize(fn) {
  const root = { children: new Map(), done: false, value: undefined };
  return function (...args) {
    let node = root;
    for (const arg of args) {
      if (!node.children.has(arg)) {
        node.children.set(arg, { children: new Map(), done: false, value: undefined });
      }
      node = node.children.get(arg);
    }
    if (!node.done) {
      node.value = fn(...args);
      node.done = true;
    }
    return node.value;
  };
}

