function memoize(fn) {
  const seen = [];
  return function (...args) {
    for (const entry of seen) {
      const same = entry.args.length === args.length && entry.args.every((value, i) => value === args[i]);
      if (same) return entry.result;
    }
    const result = fn(...args);
    seen.push({ args, result });
    return result;
  };
}

