function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const fnName = pick(['sum', 'merge', 'list']);
  const objectCount = (fnName === 'sum' ? 0 : 1) + Math.floor(rand() * (small ? 4 : 30));
  const objects = [];
  for (let i = 0; i < objectCount; i++) {
    const object = {};
    for (const key of ['a', 'b', 'c']) if (rand() < 0.4) object[key] = Math.floor(rand() * 3);
    // list may also receive arrays; merge only gets plain objects.
    objects.push(fnName === 'list' && rand() < 0.3 ? Object.values(object) : object);
  }
  const ref = () => ({ ref: Math.floor(rand() * objects.length) });
  const argument = () => {
    if (fnName === 'sum') return rand() < 0.05 ? 1000000000 : Math.floor(rand() * 5) - 1;
    if (fnName === 'merge') return ref();
    return pick([0, 1, 2, '1', '2', '', true, false, null, ref(), ref()]);
  };
  const count = small ? 1 + Math.floor(rand() * 8) : 2000;
  const inputs = [];
  for (let i = 0; i < count; i++) {
    // Repeat an earlier argument list now and then so the cache gets hits.
    if (inputs.length && rand() < 0.3) inputs.push(inputs[Math.floor(rand() * inputs.length)].slice());
    else inputs.push(Array.from({ length: Math.floor(rand() * 4) }, argument));
  }
  return [fnName, objects, inputs];
}
